def poll_next_job(self):
    if not self.ensure_worker_lock():
        logger.debug("Worker lock not held; skipping poll cycle")
        return None
    return self.queue.pop_pending()

def is_lease_valid(self, lease_id: str) -> bool:
    cached = self._local_leases.get(lease_id)
    if not cached:
        return False
    return (time.monotonic() - cached.acquired_at) < self.lease_ttl
